/// What the notebook (numpy, same maths) answered for each window.
const List<double> _expected = <double>[0.25943323840650934, 0.9950264591891712, 0.8876318743425624, 0.6457615632883361, 0.7451435185326799, 0.9563687202647051, 0.0004998131466900424, 0.0019143255615303324, 0.0003196584660532251, 0.0006224887755214201, 0.007391928155161487, 0.13568922659982793];

void main() {
  test('the Dart model gives the same numbers as the notebook', () {
    for (var i = 0; i < _windows.length; i++) {
      final p = EcgAnomalyModel.predict(_windows[i]);
      expect(p, isNotNull, reason: 'window $i');
      expect(p!, closeTo(_expected[i], 1e-6), reason: 'window $i');
    }
  });

  test('a flat line gives no answer, never an alert', () {
    final flat = List<double>.filled(EcgAnomalyModel.windowSamples, 512);
    expect(EcgAnomalyModel.predict(flat), isNull);
    final m = EcgAnomalyMonitor();
    final ds = m.addSamples(List<double>.filled(EcgAnomalyModel.windowSamples * 2, 512));
    expect(ds, isNotEmpty);
    expect(ds.every((d) => !d.signalOk && !d.alert), isTrue);
  });

  test('the monitor decides every stride and wants the window to be full first', () {
    final m = EcgAnomalyMonitor();
    expect(m.addSamples(_windows[0].sublist(0, 100)), isEmpty);
    final first = m.addSamples(_windows[0].sublist(100));
    expect(first.length, 1);
    expect(first.single.probability, closeTo(_expected[0], 1e-6));
    expect(m.addSamples(List<double>.filled(EcgAnomalyModel.strideSamples, 512)).length, 1);
  });
}
